public class Main {
    // KISS: the simplest code that meets today's need.
    static int simple(int price) { return price - price / 10; }

    // Over-engineered: a registry of policies although only one exists (YAGNI).
    static Map<String, IntUnaryOperator> registry = new HashMap<>();

    public static void main(String[] args) {
        registry.put("default", p -> p - p / 10);
        int price = 200;
        System.out.println("price=" + price);
        System.out.println("simple     = " + simple(price) + " (1 function)");
        System.out.println("engineered = " + registry.get("default").applyAsInt(price) + " (registry + lookup + key)");
        System.out.println("same answer, more to read and maintain");
    }
}

