import java.util.*;

public class Main {
    static class Bag {
        List<Integer> items = new ArrayList<>();
        void add(int x) { items.add(x); }
        // addAll calls this.add: an internal detail the child can trip over.
        void addAll(List<Integer> xs) { for (int x : xs) add(x); }
    }
    // Inheritance: counts adds, but addAll is counted twice.
    static class CountingBag extends Bag {
        int count = 0;
        @Override void add(int x) { count++; super.add(x); }
        @Override void addAll(List<Integer> xs) { count += xs.size(); super.addAll(xs); }
    }
    // Composition: uses only the public contract of Bag.
    static class CountingWrapper {
        private final Bag inner = new Bag();
        int count = 0;
        void add(int x) { count++; inner.add(x); }
        void addAll(List<Integer> xs) { count += xs.size(); inner.addAll(xs); }
    }
    public static void main(String[] args) {
        List<Integer> xs = List.of(1, 2, 3);
        CountingBag a = new CountingBag(); a.addAll(xs);
        System.out.println("added 3 items");
        System.out.println("inheritance count = " + a.count + " (wrong)");
        CountingWrapper w = new CountingWrapper();
        w.addAll(xs);
        System.out.println("composition count = " + w.count + " (right)");
    }
}

