using System;
using System.Collections.Generic;

class Bag
{
    public List<int> Items = new List<int>();
    public virtual void Add(int x) { Items.Add(x); }
    // AddAll calls Add: an internal detail the child can trip over.
    public virtual void AddAll(List<int> xs) { foreach (int x in xs) Add(x); }
}
// Inheritance: counts adds, but AddAll is counted twice.
class CountingBag : Bag
{
    public int Count = 0;
    public override void Add(int x) { Count++; base.Add(x); }
    public override void AddAll(List<int> xs) { Count += xs.Count; base.AddAll(xs); }
}
// Composition: uses only the public contract of Bag.
class CountingWrapper
{
    Bag inner = new Bag();
    public int Count = 0;
    public void AddAll(List<int> xs) { Count += xs.Count; inner.AddAll(xs); }
}
class Program
{
    static void Main()
    {
        var xs = new List<int> { 1, 2, 3 };
        Console.WriteLine("added 3 items");
        var a = new CountingBag(); a.AddAll(xs);
        Console.WriteLine("inheritance count = " + a.Count + " (wrong)");
        var w = new CountingWrapper(); w.AddAll(xs);
        Console.WriteLine("composition count = " + w.Count + " (right)");
    }
}

