public class Main {
    public static void main(String[] args) {
        // Each method is a bit mask of the fields it uses: items=1, printer=2, user=4.
        String[] names = {"total", "addItem", "print", "setPrinter", "login", "logout"};
        int[] uses = {1, 1, 2, 2, 4, 4};
        int sharing = 0, notSharing = 0;
        for (int i = 0; i < uses.length; i++) {
            for (int j = i + 1; j < uses.length; j++) {
                // a pair "shares" if both touch at least one common field
                if ((uses[i] & uses[j]) != 0) sharing++; else notSharing++;
            }
        }
        System.out.println("methods=" + names.length + " pairs=" + (sharing + notSharing));
        System.out.println("sharing=" + sharing + " notSharing=" + notSharing);
        System.out.println("LCOM=" + Math.max(0, notSharing - sharing) + " (high: three unrelated groups, split the class)");
    }
}

