public class Main {
    static class Address { String city = "Pune"; }
    static class Customer {
        private Address address = new Address();
        // Customer answers questions about its own address.
        String city() { return address.city; }
    }
    static class Order {
        private Customer customer = new Customer();
        Customer getCustomer() { return customer; }
        // Tell, Don't Ask: Order talks only to its neighbour.
        String shippingCity() { return customer.city(); }
    }
    public static void main(String[] args) {
        Order order = new Order();
        // Train wreck: caller knows Order -> Customer -> Address -> city
        System.out.println("train wreck : " + order.getCustomer().city());
        // Law of Demeter: caller knows only Order
        System.out.println("demeter     : " + order.shippingCity());
        // Fluent builder is fine: each call returns the same object, not a stranger's internals
        StringBuilder sb = new StringBuilder().append("a").append("b");
        System.out.println("builder ok  : " + sb);
    }
}

