class Triangle : IShape { int b, h; public Triangle(int b, int h) { this.b = b; this.h = h; } public int Area() { return b * h / 2; } public string Name() { return "triangle"; } }

class Program
{
    // The ONE switch: turns external data (a code) into the right object.
    static IShape FromCode(string code, int a, int b)
    {
        switch (code)
        {
            case "S": return new Square(a);
            case "R": return new Rect(a, b);
            case "T": return new Triangle(a, b);
            default: throw new ArgumentException("unknown code " + code);
        }
    }
    static void Main()
    {
        string[] codes = { "S", "R", "T" };
        int[][] dims = { new int[] { 4, 0 }, new int[] { 3, 5 }, new int[] { 6, 4 } };
        for (int i = 0; i < codes.Length; i++)
        {
            IShape sh = FromCode(codes[i], dims[i][0], dims[i][1]);
            Console.WriteLine(codes[i] + " -> " + sh.Name() + " area=" + sh.Area());   // no switch here
        }
    }
}

