public class Main {
    public static void main(String[] args) {
        String[] files = {"Order.java", "Billing.java", "Legacy.java", "Utils.java", "Mailer.java"};
        int[] changes = {120, 95, 2, 80, 10};      // commits in the last year (from git log)
        int[] complexity = {45, 70, 90, 20, 30};    // e.g. cyclomatic complexity
        int n = files.length;
        int[] score = new int[n];
        for (int i = 0; i < n; i++) score[i] = changes[i] * complexity[i];   // churn x complexity
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        java.util.Arrays.sort(order, (a, b) -> score[b] - score[a]);           // highest first
        for (int k = 0; k < n; k++) {
            int i = order[k];
            System.out.println((k + 1) + ". " + files[i] + " changes=" + changes[i] + " complexity=" + complexity[i] + " score=" + score[i]);
        }
        System.out.println("refactor first: " + files[order[0]] + " (Legacy.java is ugly but stable)");
    }
}

