    int n = files.size();
    vector<int> score(n), order(n);
    for (int i = 0; i < n; i++) { score[i] = changes[i] * complexity[i]; order[i] = i; }   // churn x complexity
    sort(order.begin(), order.end(), [&](int a, int b) { return score[a] > score[b]; });   // highest first
    for (int k = 0; k < n; k++) {
        int i = order[k];
        cout << (k + 1) << ". " << files[i] << " changes=" << changes[i] << " complexity=" << complexity[i] << " score=" << score[i] << "\n";
    }
    cout << "refactor first: " << files[order[0]] << " (Legacy.java is ugly but stable)\n";
}

